library(shiny)
library(readxl)
library(readr)
library(writexl)
library(tools)
library(magrittr)


ui <- fluidPage(
  shinyjs::useShinyjs(),
  tags$head(tags$script(HTML('
    function fixDownloadLinks() {
      const links = document.querySelectorAll(".shiny-download-link");
      links.forEach(link => {
        link.removeAttribute("download");
        link.onclick = function(e) {
          e.preventDefault();
          window.location.href = this.href;
        };
      });
    }
    $(document).on("shiny:connected shiny:value", fixDownloadLinks);
  '))),
  titlePanel("Data Assignment Tool"),
  sidebarLayout(
    sidebarPanel(
      # h4(strong("Instructions")),
      # p("1. Upload your dataset"),
      # p("2. Select observation column"),
      # p("3. Choose assignment type and set parameters"),
      # p("4. Assign values"),
      # p("5. Update assignments"),
      # p("6. Download the modified dataset"),
      
      # fileInput("file", "Choose Data File", accept = c(".csv", ".xlsx", ".xls", ".txt")),
      fileInput("file", "1. Upload your dataset", accept = c(".csv", ".xlsx", ".xls", ".txt")),
      
      conditionalPanel(
        condition = "input.file && /\\.txt$/.test(input.file.name)",
        radioButtons("delimiter", "Text File Delimiter",
                     choices = c(Comma = ",", Semicolon = ";", Tab = "\\t"),
                     selected = ",")
      ),
      
      selectInput("observation_col", "2. Select Observation/Session Column", choices = NULL),
      
      checkboxGroupInput(
        "assignment_type", 
        "3. Choose What to Assign",
        choices = c(
          "IDs" = "id",
          "Phases" = "phase",
          "Groups" = "group"
        ),
        selected = c("id", "phase", "group")
      ),
      
      conditionalPanel(
        condition = "input.assignment_type.includes('phase')",
        textInput("possible_phases", "4. Set Possible Treatment Phases (comma-separated)",
                  value = "Baseline, Treatment, Followup")
      ),
      
      conditionalPanel(
        condition = "input.assignment_type.includes('group')",
        textInput("predefined_groups", "5. Set predefined Groups (comma-separated)",
                  value = "Control, Treatment, Placebo"),
        radioButtons("id_source", "6. Select ID Source for Group Assignment",
                     choices = c("Use existing ID variable" = "existing",
                                 "Assign new IDs" = "new"),
                     selected = "existing"),
        conditionalPanel(
          condition = "input.id_source == 'existing'",
          selectInput("existing_id_col", 
                      tags$span(" Select Existing ID Column", style = "font-weight: normal;"),
                      choices = NULL)
        )
      ),
      
      conditionalPanel(
        condition = "input.assignment_type.includes('id')",
        numericInput("max_id",
                     tags$span(" Set Maximum ID Number", style = "font-weight: normal;"),
                     value = 10, min = 1)
      ),
      
      h5(strong("7. Initialize assignment procedure")),
      fluidRow(
        column(12, 
               actionButton("init_assign",
                            label = tagList(
                              icon("play-circle"), 
                              " Initialize Assignment"
                            ),
                            class = "btn-primary", width = "100%"))
      ),
      
      h5(strong("8. Save/update assignments")),
      fluidRow(
        column(12, 
               actionButton("update_btn",
                            label = tagList(
                              icon("sync-alt"), 
                              " Update Assignments"
                            ),
                            class = "btn-info", width = "100%"))
        
      ),
      
      h5(strong("9. Download modified dataset")),
      h6("Update assignments with the final values before downloading"),
      
      radioButtons("download_format",
                   tags$span(" Download Format", style = "font-weight: normal;"),
                   choices = c("Excel (.xlsx)" = "xlsx", "CSV (.csv)" = "csv"),
                   selected = "xlsx"),
      
      # actionButton("init_assign", "Initialize Assignment"),
      # actionButton("update_btn", "Update Assignments"),
      # downloadButton("download", "Download Modified Data")

      
      
      
      fluidRow(
        column(12, 
               div(style = "width: 100%;",
                   downloadButton("download", " Download Modified Data",
                            class = "btn-secondary", style = "width: 100%;"))
        )
      )
    ),
    
    mainPanel(
      conditionalPanel(
        condition = "input.init_assign > 0",
        tabsetPanel(
          id = "main_tabs",
          
          tabPanel("ID Assignment", value = "id_tab",
                   div(style = "margin: 20px 15px 30px 0px;",  # top, right, bottom, left
                       div(class = "well",
                           style = "background-color: #f8f9fa; padding: 10px; margin-bottom: 20px;",
                           p(icon("info-circle"),
                             # strong("Info: "),
                             " Assign numeric IDs for each session using drop-down menu."
                           ),
                       ),
                   ),
                   div(style = "margin: 20px 15px 30px 10px;",  # top, right, bottom, left
                       uiOutput("id_assignment_ui")
                   )),
          tabPanel("Phase Assignment", value = "phase_tab",
                   div(style = "margin: 20px 15px 30px 0px;",  # top, right, bottom, left
                       div(class = "well",
                           style = "background-color: #f8f9fa; padding: 10px; margin-bottom: 20px;",
                           p(icon("info-circle"),
                             # strong("Info: "),
                             " Assign a predefined phase for each session using drop-down menu."
                           ),
                       ),
                   ),
                   div(style = "margin: 20px 15px 30px 10px;",  # top, right, bottom, left
                       uiOutput("phase_assignment_ui")
                   )),
          tabPanel("Group Assignment", value = "group_tab",
                   div(style = "margin: 20px 15px 30px 0px;",
                       div(class = "well",
                           style = "background-color: #f8f9fa; padding: 10px; margin-bottom: 20px;",
                           p(icon("info-circle"),
                             strong("Group assignment options:"),
                             br(),
                             "• ",
                             em("Use existing ID variable"),
                             " - When your dataset already contains participant IDs",
                             br(),
                             "• ",
                             em("Assign new IDs"),
                             " - To create groups based on IDs generated in this app"
                           )
                       )
                   ),
                   # div(style = "margin: 20px 15px 30px 0px;",
                   #     div(class = "well",
                   #         style = "background-color: #f8f9fa; padding: 10px; margin-bottom: 20px;",
                   #         p(icon("info-circle"),
                   #           "Update assignments before downloading dataset"
                   #         )
                   #     )
                   # ),
                   div(style = "margin: 20px 15px 30px 10px;",  # top, right, bottom, left
                       uiOutput("group_assignment_ui")
                   )),
          tabPanel("Summary", value = "summary_tab",
                   div(style = "margin: 20px 15px 30px 0px;",  # top, right, bottom, left
                       div(class = "well",
                           style = "background-color: #f8f9fa; padding: 10px; margin-bottom: 20px;",
                           p(icon("info-circle"),
                             # strong("Info: "),
                             " Use 'Update Assignments' button to update the tables."
                           ),
                       ),
                   ),
                   div(style = "margin: 20px 15px 30px 10px;",  # top, right, bottom, left
                       h4("ID Assignment Summary"),
                       tableOutput("id_summary_table"),
                       br(),
                       h4("Phase Assignment Summary"),
                       tableOutput("phase_summary_table"),
                       br(),
                       h4("Group Assignment Summary"),
                       tableOutput("group_summary_table")
                   ),
                   )
        )
      )
    )
  )
)

server <- function(input, output, session) {
  # rv <- reactiveValues(data = NULL, unique_obs = NULL, unique_ids = NULL, initialized = FALSE)
  rv <- reactiveValues(
    data = NULL,
    unique_obs = NULL,
    unique_ids = NULL,
    initialized = FALSE,
    id_assignments = list(),
    phase_assignments = list(),
    group_assignments = list(),
    last_update = NULL
  )
  
  read_data_file <- function(filepath, ext, delimiter = ",") {
    switch(ext,
           "csv" = read.csv(filepath),
           "xlsx" = read_excel(filepath),
           "xls" = read_excel(filepath),
           "txt" = read_delim(filepath, delim = delimiter),
           stop("Unsupported file type")
    )
  }
  
  
  
  
  observeEvent(input$file, {
    req(input$file)
    ext <- tools::file_ext(input$file$name)
    
    tryCatch({
      # Leer archivo
      if (ext == "txt") {
        rv$data <- read_data_file(input$file$datapath, ext, input$delimiter)
      } else {
        rv$data <- read_data_file(input$file$datapath, ext)
      }
      
      if (inherits(rv$data, "tbl_df")) rv$data <- as.data.frame(rv$data)
      
      # 1. Actualizar lista de grupos si existe columna "Group"
      if ("Group" %in% names(rv$data)) {
        existing_groups <- unique(na.omit(rv$data$Group))
        if (length(existing_groups) > 0) {
          # Combinar con grupos ya definidos (evitando duplicados)
          current_groups <- trimws(unlist(strsplit(input$predefined_groups, ",")))
          all_groups <- unique(c(current_groups, existing_groups))
          updateTextInput(session, "predefined_groups",
                          value = paste(all_groups, collapse = ", "))
        }
      }
      
      # 2. Actualizar lista de fases si existe columna "Treatment_Phase"
      if ("Treatment_Phase" %in% names(rv$data)) {
        existing_phases <- unique(na.omit(rv$data$Treatment_Phase))
        if (length(existing_phases) > 0) {
          current_phases <- trimws(unlist(strsplit(input$possible_phases, ",")))
          all_phases <- unique(c(current_phases, existing_phases))
          updateTextInput(session, "possible_phases",
                          value = paste(all_phases, collapse = ", "))
        }
      }
      
      # Resto de tu lógica de inicialización...
      existing_cols <- names(rv$data)
      updateSelectInput(session, "observation_col", 
                        choices = existing_cols,
                        selected = ifelse("observation" %in% existing_cols, 
                                          "observation", 
                                          existing_cols[1]))
      
      updateSelectInput(session, "existing_id_col",
                        choices = existing_cols,
                        selected = ifelse("ID" %in% existing_cols, "ID", character(0)))
      
    }, error = function(e) {
      showNotification(paste("Error reading file:", e$message), type = "error")
    })
  })
  
  observeEvent(input$assignment_type, {
    if (length(input$assignment_type) == 0) return()
    
    if ("id" %in% input$assignment_type) {
      updateTabsetPanel(session, "main_tabs", selected = "id_tab")
    } else if ("phase" %in% input$assignment_type) {
      updateTabsetPanel(session, "main_tabs", selected = "phase_tab")
    } else if ("group" %in% input$assignment_type) {
      updateTabsetPanel(session, "main_tabs", selected = "group_tab")
    }
  })
  
  # observeEvent(input$init_assign, {
  #   req(rv$data, input$observation_col)
  #   
  #   if (!"ID" %in% names(rv$data)) rv$data$ID <- NA_character_
  #   if (!"Treatment_Phase" %in% names(rv$data)) rv$data$Treatment_Phase <- NA_character_
  #   if (!"Group" %in% names(rv$data)) rv$data$Group <- NA_character_
  #   
  #   rv$unique_obs <- unique(rv$data[[input$observation_col]])
  #   rv$unique_ids <- unique(na.omit(rv$data$ID))
  #   rv$initialized <- TRUE
  # })
  
  observeEvent(input$init_assign, {
    req(rv$data, input$observation_col)
    
    if (!"ID" %in% names(rv$data)) rv$data$ID <- NA_character_
    if (!"Treatment_Phase" %in% names(rv$data)) rv$data$Treatment_Phase <- NA_character_
    if (!"Group" %in% names(rv$data)) rv$data$Group <- NA_character_
    
    rv$unique_obs <- unique(rv$data[[input$observation_col]])
    rv$unique_ids <- unique(na.omit(rv$data$ID))
    rv$initialized <- TRUE
    
    # Forzar la primera actualización
    rv$last_update <- Sys.time()
  })
  
  observeEvent(input$update_btn, {
    req(rv$initialized, rv$data)
    
    # Actualizar IDs
    if ("id" %in% input$assignment_type) {
      lapply(seq_along(rv$unique_obs), function(i) {
        if (!is.null(input[[paste0("id_", i)]])) {
          obs <- rv$unique_obs[i]
          new_id <- if (input[[paste0("id_", i)]] == "Unassigned") NA else input[[paste0("id_", i)]]
          rv$data$ID[rv$data[[input$observation_col]] == obs] <- new_id
          
          if ("group" %in% input$assignment_type && 
              input$id_source == "existing" && 
              !is.null(input$existing_id_col) && 
              input$existing_id_col != "") {
            rv$data[[input$existing_id_col]][rv$data[[input$observation_col]] == obs] <- new_id
          }
        }
      })
      rv$unique_ids <- unique(na.omit(rv$data$ID))
    }
    
    # Actualizar Phases
    if ("phase" %in% input$assignment_type) {
      lapply(seq_along(rv$unique_obs), function(i) {
        if (!is.null(input[[paste0("phase_", i)]])) {
          obs <- rv$unique_obs[i]
          new_phase <- if (input[[paste0("phase_", i)]] == "Unassigned") NA else input[[paste0("phase_", i)]]
          rv$data$Treatment_Phase[rv$data[[input$observation_col]] == obs] <- new_phase
        }
      })
    }
    
    # Actualizar Groups
    # if ("group" %in% input$assignment_type) {
    #   current_ids <- if (input$id_source == "existing" && !is.null(input$existing_id_col) && input$existing_id_col != "") {
    #     unique(na.omit(rv$data[[input$existing_id_col]]))
    #   } else {
    #     unique(na.omit(rv$data$ID))
    #   }
    #   
    #   if (length(current_ids) > 0) {
    #     lapply(seq_along(current_ids), function(i) {
    #       if (!is.null(input[[paste0("group_", i)]])) {
    #         id <- current_ids[i]
    #         new_group <- if (input[[paste0("group_", i)]] == "Unassigned") NA else input[[paste0("group_", i)]]
    #         id_col <- if (input$id_source == "existing" && !is.null(input$existing_id_col)) input$existing_id_col else "ID"
    #         rv$data$Group[rv$data[[id_col]] == id] <- new_group
    #       }
    #     })
    #   }
    # }
    
    if ("group" %in% input$assignment_type) {
      # Obtener IDs según la fuente seleccionada
      id_values <- if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
        rv$data[[input$existing_id_col]]
      } else {
        rv$data$ID
      }
      
      # Procesar cada grupo
      lapply(seq_along(unique(na.omit(id_values))), function(i) {
        if (!is.null(input[[paste0("group_", i)]])) {
          current_id <- unique(na.omit(id_values))[i]
          new_group <- if (input[[paste0("group_", i)]] == "Unassigned") NA else input[[paste0("group_", i)]]
          
          # Actualizar todos los registros con este ID
          if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
            rv$data$Group[rv$data[[input$existing_id_col]] == current_id] <- new_group
          } else {
            rv$data$Group[rv$data$ID == current_id] <- new_group
          }
        }
      })
    }
    
    # Forzar actualización de la UI
    rv$last_update <- Sys.time()
    showNotification("Assignments updated successfully", type = "message")
  })
  
  
  
  # Observers para actualizar los UI (sin cambiar los datos)
  lapply(c("id", "phase", "group"), function(type) {
    output[[paste0(type, "_assignment_ui")]] <- renderUI({
      req(rv$initialized, rv$data, type %in% input$assignment_type)
      
      output$id_assignment_ui <- renderUI({
        # req(rv$initialized, rv$unique_obs, 
        #     input$assignment_type %in% c("id", "id_phase", "id_group", "all"))
        req(rv$initialized, rv$unique_obs, "id" %in% input$assignment_type)
        
        # Determinar si estamos usando IDs existentes
        use_existing_ids <- "id" %in% input$assignment_type && 
          input$id_source == "existing" && 
          !is.null(input$existing_id_col) && 
          input$existing_id_col != ""
        
        if (use_existing_ids) {
          # Modo: Usar IDs existentes de columna personalizada
          req(input$existing_id_col %in% names(rv$data))
          existing_ids <- unique(na.omit(rv$data[[input$existing_id_col]]))
          valid_ids <- as.character(sort(existing_ids))
        } else {
          # Modo: Asignar nuevos IDs
          req(input$max_id)
          valid_ids <- as.character(seq(1, input$max_id))
        }
        
        lapply(seq_along(rv$unique_obs), function(i) {
          obs <- rv$unique_obs[i]
          
          # Obtener ID actual (dependiendo del modo)
          current_id <- if (use_existing_ids) {
            as.character(unique(rv$data[[input$existing_id_col]][rv$data[[input$observation_col]] == obs]))
          } else if ("ID" %in% names(rv$data)) {
            as.character(unique(rv$data$ID[rv$data[[input$observation_col]] == obs]))
          } else {
            "Unassigned"
          }
          
          # Manejar casos donde current_id es NA o tiene múltiples valores
          current_id <- if (length(current_id) == 0 || all(is.na(current_id))) {
            "Unassigned"
          } else {
            current_id[1]  # Tomar el primer valor si hay múltiples
          }
          
          fluidRow(
            column(6, p(strong(paste("Observation:", obs)))),
            column(6, selectInput(
              paste0("id_", i), NULL,
              choices = c("Unassigned", valid_ids),
              selected = current_id
            ))
          )
        })
      })
      
      
      
      output$phase_assignment_ui <- renderUI({
        # req(rv$initialized, rv$unique_obs, input$possible_phases,
        #     input$assignment_type %in% c("phase", "id_phase", "phase_group", "all"))
        req(rv$initialized, rv$unique_obs, input$possible_phases,
            "phase" %in% input$assignment_type)
        
        # Obtener todas las fases posibles (combinando predefinidas y existentes)
        predefined_phases <- trimws(unlist(strsplit(input$possible_phases, ",")))
        
        # Si hay datos cargados con fases, añadirlas a las opciones
        if (!is.null(rv$data) && "Treatment_Phase" %in% names(rv$data)) {
          existing_phases <- unique(na.omit(rv$data$Treatment_Phase))
          all_phases <- unique(c(predefined_phases, existing_phases))
        } else {
          all_phases <- predefined_phases
        }
        
        # Ordenar las fases alfabéticamente
        all_phases <- sort(all_phases)
        
        lapply(seq_along(rv$unique_obs), function(i) {
          obs <- rv$unique_obs[i]
          current_phase <- if (!is.null(rv$data$Treatment_Phase) && 
                               !is.na(rv$data$Treatment_Phase[rv$data[[input$observation_col]] == obs][1])) {
            rv$data$Treatment_Phase[rv$data[[input$observation_col]] == obs][1]
          } else {
            "Unassigned"
          }
          
          fluidRow(
            column(6, p(strong(paste("Observation:", obs)))),
            column(6, selectInput(
              paste0("phase_", i), NULL,
              choices = c("Unassigned", all_phases),
              selected = current_phase
            ))
          )
        })
      })
      
      
      # output$group_assignment_ui <- renderUI({
      #   req(rv$initialized, input$predefined_groups,
      #       "group" %in% input$assignment_type, rv$last_update)  # Añadir dependencia a rv$last_update
      #   
      #   # Obtener los IDs según la fuente seleccionada
      #   if (input$id_source == "existing" && !is.null(input$existing_id_col) && input$existing_id_col != "") {
      #     req(input$existing_id_col %in% names(rv$data))
      #     unique_ids <- unique(na.omit(rv$data[[input$existing_id_col]]))
      #   } else {
      #     unique_ids <- unique(na.omit(rv$data$ID))
      #   }
      #   
      #   if (length(unique_ids) == 0) {
      #     return(div(class = "alert alert-warning", 
      #                "There are no IDs available. Please assign IDs and update assignments with 'Update Assignments' button."))
      #   }
      #   
      #   predefined_groups <- trimws(unlist(strsplit(input$predefined_groups, ",")))
      #   
      #   # Obtener las asignaciones actuales antes de crear los inputs
      #   current_assignments <- sapply(seq_along(unique_ids), function(i) {
      #     id <- unique_ids[i]
      #     if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
      #       unique(rv$data$Group[rv$data[[input$existing_id_col]] == id])
      #     } else {
      #       unique(rv$data$Group[rv$data$ID == id])
      #     }
      #   })
      #   
      #   lapply(seq_along(unique_ids), function(i) {
      #     id <- unique_ids[i]
      #     current_group <- if (length(current_assignments[[i]]) == 1) current_assignments[[i]] else "Unassigned"
      #     
      #     fluidRow(
      #       column(6, p(strong(paste("ID:", id)))),
      #              column(6, selectInput(
      #                paste0("group_", i), NULL,
      #                choices = c("Unassigned", predefined_groups),
      #                selected = current_group
      #              ))
      #       )
      #   })
      # })
      
      output$group_assignment_ui <- renderUI({
        req(rv$initialized, input$predefined_groups, 
            "group" %in% input$assignment_type, rv$last_update)
        
        # Obtener IDs según configuración
        id_values <- if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
          req(input$existing_id_col %in% names(rv$data))
          unique(na.omit(rv$data[[input$existing_id_col]]))
        } else {
          unique(na.omit(rv$data$ID))
        }
        
        if (length(id_values) == 0) {
          return(div(class = "alert alert-warning",
                     "No valid IDs found. Please assign IDs first."))
        }
        
        predefined_groups <- trimws(unlist(strsplit(input$predefined_groups, ",")))
        
        # Crear un input por cada ID único
        lapply(seq_along(id_values), function(i) {
          current_id <- id_values[i]
          
          # Obtener el grupo actual para este ID
          current_group <- if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
            unique(na.omit(rv$data$Group[rv$data[[input$existing_id_col]] == current_id]))
          } else {
            unique(na.omit(rv$data$Group[rv$data$ID == current_id]))
          }
          
          # Manejar casos múltiples o NA
          selected_value <- if (length(current_group) == 1) current_group else "Unassigned"
          
          fluidRow(
            column(6, p(strong(paste("ID:", current_id)))),
                   column(6, selectInput(
                     inputId = paste0("group_", i),
                     label = NULL,
                     choices = c("Unassigned", predefined_groups),
                     selected = selected_value
                   ))
            )
        })
      })
      
    })
  })
  
  # Observers para los summary tables que dependen del último update
  observe({
    req(rv$last_update)  # Esto hace que las tablas solo se actualicen cuando cambia last_update
    
    output$id_summary_table <- renderTable({
      req(rv$initialized, rv$data, input$max_id, "id" %in% input$assignment_type)
      
      valid_ids <- as.character(seq(1, input$max_id))
      
      data.frame(
        ID = c(valid_ids, "Unassigned"),
        Count = c(
          sapply(valid_ids, function(id) sum(rv$data$ID == id, na.rm = TRUE)),
          sum(is.na(rv$data$ID))
        )
      )
    }, striped = TRUE, hover = TRUE, bordered = TRUE)
    
    output$phase_summary_table <- renderTable({
      req(rv$initialized, rv$data, input$possible_phases, "phase" %in% input$assignment_type)
      
      predefined_phases <- trimws(unlist(strsplit(input$possible_phases, ",")))
      if (!is.null(rv$data) && "Treatment_Phase" %in% names(rv$data)) {
        existing_phases <- unique(na.omit(rv$data$Treatment_Phase))
        all_phases <- unique(c(predefined_phases, existing_phases))
      } else {
        all_phases <- predefined_phases
      }
      
      data.frame(
        Phase = c(sort(all_phases), "Unassigned"),
        Count = c(
          sapply(sort(all_phases), function(p) sum(rv$data$Treatment_Phase == p, na.rm = TRUE)),
          sum(is.na(rv$data$Treatment_Phase))
        )
      )
    }, striped = TRUE, hover = TRUE, bordered = TRUE)
    
    output$group_summary_table <- renderTable({
      req(rv$initialized, rv$data, input$predefined_groups, "group" %in% input$assignment_type)
      
      predefined_groups <- trimws(unlist(strsplit(input$predefined_groups, ",")))
      
      data.frame(
        Group = c(predefined_groups, "Unassigned"),
        Count = c(
          sapply(predefined_groups, function(g) sum(rv$data$Group == g, na.rm = TRUE)),
          sum(is.na(rv$data$Group))
        )
      )
    }, striped = TRUE, hover = TRUE, bordered = TRUE)
  })
  
  output$download <- downloadHandler(
    filename = function() {
      paste0("assigned_data_", Sys.Date(), ".", 
             ifelse(input$download_format == "xlsx", "xlsx", "csv"))
    },
    content = function(file) {
      req(rv$data)
      
      # 1. Identificar columnas y nombres originales
      original_cols <- names(rv$data)
      has_original_id <- "ID" %in% original_cols || input$existing_id_col
      original_id_col <- ifelse(has_original_id, "ID", input$existing_id_col)
      
      # 2. Determinar qué columnas incluir
      cols_to_keep <- c(input$observation_col)
      
      # Lógica para columnas especiales (ID/Phase/Group)
      if ("id" %in% input$assignment_type) {
        if (!is.null(original_id_col)) {
          cols_to_keep <- c(cols_to_keep, original_id_col)
        }
      } else if (!is.null(input$existing_id_col)) {
        cols_to_keep <- c(cols_to_keep, input$existing_id_col)
      } else {
        cols_to_keep <- c(cols_to_keep, "ID")
      }
      
      if ("phase" %in% input$assignment_type || "Treatment_Phase" %in% original_cols) {
        cols_to_keep <- c(cols_to_keep, "Treatment_Phase")
      }
      
      if ("group" %in% input$assignment_type || "Group" %in% original_cols) {
        cols_to_keep <- c(cols_to_keep, "Group")
      }
      
      # 3. Añadir otras columnas manteniendo orden original
      other_cols <- setdiff(original_cols, 
                            c("ID", "Treatment_Phase", "Group", input$observation_col))
      cols_to_keep <- unique(c(cols_to_keep, other_cols))
      
      # 4. Orden final (mantener orden original + nuevas al final)
      final_cols <- intersect(original_cols, cols_to_keep)  # Columnas originales en su orden
      new_cols <- setdiff(cols_to_keep, original_cols)     # Columnas nuevas a añadir
      final_cols <- c(final_cols, new_cols)                # Combinar manteniendo orden
      
      # 5. Crear subset asegurando que no hay columnas vacías
      download_data <- rv$data[, final_cols, drop = FALSE]
      
      # 6. Eliminar columnas completamente vacías que no existían originalmente
      if (!has_original_id && ("ID" %in% names(download_data))) {
        if (all(is.na(download_data$ID))) {
          download_data$ID <- NULL
        }
      }
      
      # 7. Generar archivo
      if (input$download_format == "xlsx") {
        write_xlsx(download_data, file)
      } else {
        readr::write_excel_csv(download_data, file)
      }
    }
  )
}

