    #         rv$data$Group[rv$data[[id_col]] == id] <- new_group
    #       }
    #     })
    #   }
    # }
    
    if ("group" %in% input$assignment_type) {
      # Obtener IDs según la fuente seleccionada
      id_values <- if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
        rv$data[[input$existing_id_col]]
      } else {
        rv$data$ID
      }
      
      # Procesar cada grupo
      lapply(seq_along(unique(na.omit(id_values))), function(i) {
        if (!is.null(input[[paste0("group_", i)]])) {
          current_id <- unique(na.omit(id_values))[i]
          new_group <- if (input[[paste0("group_", i)]] == "Unassigned") NA else input[[paste0("group_", i)]]
          
          # Actualizar todos los registros con este ID
          if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
            rv$data$Group[rv$data[[input$existing_id_col]] == current_id] <- new_group
          } else {
            rv$data$Group[rv$data$ID == current_id] <- new_group
          }
        }
      })
    }
    
    # Forzar actualización de la UI
    rv$last_update <- Sys.time()
    showNotification("Assignments updated successfully", type = "message")
  })
  
  
  
  # Observers para actualizar los UI (sin cambiar los datos)
  lapply(c("id", "phase", "group"), function(type) {
