      #   lapply(seq_along(unique_ids), function(i) {
      #     id <- unique_ids[i]
      #     current_group <- if (length(current_assignments[[i]]) == 1) current_assignments[[i]] else "Unassigned"
      #     
      #     fluidRow(
      #       column(6, p(strong(paste("ID:", id)))),
      #              column(6, selectInput(
      #                paste0("group_", i), NULL,
      #                choices = c("Unassigned", predefined_groups),
      #                selected = current_group
      #              ))
      #       )
      #   })
      # })
      
      output$group_assignment_ui <- renderUI({
        req(rv$initialized, input$predefined_groups, 
            "group" %in% input$assignment_type, rv$last_update)
        
        # Obtener IDs según configuración
        id_values <- if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
          req(input$existing_id_col %in% names(rv$data))
          unique(na.omit(rv$data[[input$existing_id_col]]))
        } else {
          unique(na.omit(rv$data$ID))
        }
        
        if (length(id_values) == 0) {
          return(div(class = "alert alert-warning",
                     "No valid IDs found. Please assign IDs first."))
        }
        
        predefined_groups <- trimws(unlist(strsplit(input$predefined_groups, ",")))
        
        # Crear un input por cada ID único
        lapply(seq_along(id_values), function(i) {
          current_id <- id_values[i]
          
          # Obtener el grupo actual para este ID
          current_group <- if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
            unique(na.omit(rv$data$Group[rv$data[[input$existing_id_col]] == current_id]))
          } else {
            unique(na.omit(rv$data$Group[rv$data$ID == current_id]))
          }
          
          # Manejar casos múltiples o NA
          selected_value <- if (length(current_group) == 1) current_group else "Unassigned"
          
          fluidRow(
            column(6, p(strong(paste("ID:", current_id)))),
                   column(6, selectInput(
                     inputId = paste0("group_", i),
                     label = NULL,
                     choices = c("Unassigned", predefined_groups),
                     selected = selected_value
                   ))
            )
        })
      })
      
    })
  })
  
  # Observers para los summary tables que dependen del último update
  observe({
    req(rv$last_update)  # Esto hace que las tablas solo se actualicen cuando cambia last_update
    
    output$id_summary_table <- renderTable({
      req(rv$initialized, rv$data, input$max_id, "id" %in% input$assignment_type)
      
      valid_ids <- as.character(seq(1, input$max_id))
      
      data.frame(
        ID = c(valid_ids, "Unassigned"),
        Count = c(
          sapply(valid_ids, function(id) sum(rv$data$ID == id, na.rm = TRUE)),
          sum(is.na(rv$data$ID))
        )
      )
    }, striped = TRUE, hover = TRUE, bordered = TRUE)
    
    output$phase_summary_table <- renderTable({
      req(rv$initialized, rv$data, input$possible_phases, "phase" %in% input$assignment_type)
      
      predefined_phases <- trimws(unlist(strsplit(input$possible_phases, ",")))
      if (!is.null(rv$data) && "Treatment_Phase" %in% names(rv$data)) {
        existing_phases <- unique(na.omit(rv$data$Treatment_Phase))
        all_phases <- unique(c(predefined_phases, existing_phases))
      } else {
        all_phases <- predefined_phases
      }
      
      data.frame(
        Phase = c(sort(all_phases), "Unassigned"),
        Count = c(
          sapply(sort(all_phases), function(p) sum(rv$data$Treatment_Phase == p, na.rm = TRUE)),
          sum(is.na(rv$data$Treatment_Phase))
        )
      )
    }, striped = TRUE, hover = TRUE, bordered = TRUE)
    
    output$group_summary_table <- renderTable({
      req(rv$initialized, rv$data, input$predefined_groups, "group" %in% input$assignment_type)
      
      predefined_groups <- trimws(unlist(strsplit(input$predefined_groups, ",")))
      
      data.frame(
        Group = c(predefined_groups, "Unassigned"),
        Count = c(
          sapply(predefined_groups, function(g) sum(rv$data$Group == g, na.rm = TRUE)),
          sum(is.na(rv$data$Group))
        )
      )
    }, striped = TRUE, hover = TRUE, bordered = TRUE)
  })
  
  output$download <- downloadHandler(
    filename = function() {
      paste0("assigned_data_", Sys.Date(), ".", 
             ifelse(input$download_format == "xlsx", "xlsx", "csv"))
    },
    content = function(file) {
      req(rv$data)
      
      # 1. Identificar columnas y nombres originales
      original_cols <- names(rv$data)
      has_original_id <- "ID" %in% original_cols || input$existing_id_col
      original_id_col <- ifelse(has_original_id, "ID", input$existing_id_col)
      
      # 2. Determinar qué columnas incluir
      cols_to_keep <- c(input$observation_col)
      
      # Lógica para columnas especiales (ID/Phase/Group)
      if ("id" %in% input$assignment_type) {
        if (!is.null(original_id_col)) {
          cols_to_keep <- c(cols_to_keep, original_id_col)
        }
      } else if (!is.null(input$existing_id_col)) {
        cols_to_keep <- c(cols_to_keep, input$existing_id_col)
      } else {
        cols_to_keep <- c(cols_to_keep, "ID")
      }
      
      if ("phase" %in% input$assignment_type || "Treatment_Phase" %in% original_cols) {
        cols_to_keep <- c(cols_to_keep, "Treatment_Phase")
      }
      
      if ("group" %in% input$assignment_type || "Group" %in% original_cols) {
        cols_to_keep <- c(cols_to_keep, "Group")
      }
      
      # 3. Añadir otras columnas manteniendo orden original
      other_cols <- setdiff(original_cols, 
                            c("ID", "Treatment_Phase", "Group", input$observation_col))
      cols_to_keep <- unique(c(cols_to_keep, other_cols))
      
      # 4. Orden final (mantener orden original + nuevas al final)
      final_cols <- intersect(original_cols, cols_to_keep)  # Columnas originales en su orden
      new_cols <- setdiff(cols_to_keep, original_cols)     # Columnas nuevas a añadir
      final_cols <- c(final_cols, new_cols)                # Combinar manteniendo orden
      
      # 5. Crear subset asegurando que no hay columnas vacías
      download_data <- rv$data[, final_cols, drop = FALSE]
      
      # 6. Eliminar columnas completamente vacías que no existían originalmente
      if (!has_original_id && ("ID" %in% names(download_data))) {
        if (all(is.na(download_data$ID))) {
          download_data$ID <- NULL
        }
      }
      
      # 7. Generar archivo
      if (input$download_format == "xlsx") {
        write_xlsx(download_data, file)
      } else {
        readr::write_excel_csv(download_data, file)
      }
    }
  )
}

