server <- function(input, output, session) {
  # rv <- reactiveValues(data = NULL, unique_obs = NULL, unique_ids = NULL, initialized = FALSE)
  rv <- reactiveValues(
    data = NULL,
    unique_obs = NULL,
    unique_ids = NULL,
    initialized = FALSE,
    id_assignments = list(),
    phase_assignments = list(),
    group_assignments = list()
  )
  
  read_data_file <- function(filepath, ext, delimiter = ",") {
    switch(ext,
           "csv" = read.csv(filepath),
           "xlsx" = read_excel(filepath),
           "xls" = read_excel(filepath),
           "txt" = read_delim(filepath, delim = delimiter),
           stop("Unsupported file type")
    )
  }
  
  
  observeEvent(input$file, {
    req(input$file)
    ext <- tools::file_ext(input$file$name)
    
    tryCatch({
      if (ext == "txt") {
        rv$data <- read_data_file(input$file$datapath, ext, input$delimiter)
      } else {
        rv$data <- read_data_file(input$file$datapath, ext)
      }
      
      if (inherits(rv$data, "tbl_df")) rv$data <- as.data.frame(rv$data)
      
      # Obtener solo columnas existentes
      existing_cols <- names(rv$data)
      
      # Actualizar selectores con validación
      updateSelectInput(session, "observation_col", 
                        choices = existing_cols,
                        selected = ifelse("observation" %in% existing_cols, "observation", character(0)))
      
      updateSelectInput(session, "existing_id_col",
                        choices = existing_cols,
                        selected = ifelse("ID" %in% existing_cols, "ID", character(0)))
      
      rv$initialized <- FALSE
    }, error = function(e) {
      showNotification(paste("Error reading file:", e$message), type = "error")
    })
  })
  
  observeEvent(input$assignment_type, {
    if (length(input$assignment_type) == 0) return()
    
    if ("id" %in% input$assignment_type) {
      updateTabsetPanel(session, "main_tabs", selected = "id_tab")
    } else if ("phase" %in% input$assignment_type) {
      updateTabsetPanel(session, "main_tabs", selected = "phase_tab")
    } else if ("group" %in% input$assignment_type) {
      updateTabsetPanel(session, "main_tabs", selected = "group_tab")
    }
  })
  
  
  
  observeEvent(input$init_assign, {
    req(rv$data, input$observation_col)
    
    # Inicializar columnas si no existen
    if (!"ID" %in% names(rv$data)) rv$data$ID <- NA_character_
    if (!"Treatment_Phase" %in% names(rv$data)) rv$data$Treatment_Phase <- NA_character_
    if (!"Group" %in% names(rv$data)) rv$data$Group <- NA_character_
    
    # Actualizar valores únicos
    rv$unique_obs <- unique(rv$data[[input$observation_col]])
    rv$unique_ids <- unique(na.omit(rv$data$ID))
    
    # Inicializar asignaciones
    rv$id_assignments <- setNames(as.list(rep(NA, length(rv$unique_obs))), rv$unique_obs)
    rv$phase_assignments <- setNames(as.list(rep(NA, length(rv$unique_obs))), rv$unique_obs)
    rv$group_assignments <- setNames(as.list(rep(NA, length(rv$unique_ids))), rv$unique_ids)
    
    rv$initialized <- TRUE
  })
  
  
  
  output$id_assignment_ui <- renderUI({
    # req(rv$initialized, rv$unique_obs, 
    #     input$assignment_type %in% c("id", "id_phase", "id_group", "all"))
    req(rv$initialized, rv$unique_obs, "id" %in% input$assignment_type)
    
    # Determinar si estamos usando IDs existentes
    use_existing_ids <- "id" %in% input$assignment_type && 
      input$id_source == "existing" && 
      !is.null(input$existing_id_col) && 
      input$existing_id_col != ""
    
    if (use_existing_ids) {
      # Modo: Usar IDs existentes de columna personalizada
      req(input$existing_id_col %in% names(rv$data))
      existing_ids <- unique(na.omit(rv$data[[input$existing_id_col]]))
      valid_ids <- as.character(sort(existing_ids))
    } else {
      # Modo: Asignar nuevos IDs
      req(input$max_id)
      valid_ids <- as.character(seq(1, input$max_id))
    }
    
    lapply(seq_along(rv$unique_obs), function(i) {
      obs <- rv$unique_obs[i]
      
      # Obtener ID actual (dependiendo del modo)
      current_id <- if (use_existing_ids) {
        as.character(unique(rv$data[[input$existing_id_col]][rv$data[[input$observation_col]] == obs]))
      } else if ("ID" %in% names(rv$data)) {
        as.character(unique(rv$data$ID[rv$data[[input$observation_col]] == obs]))
      } else {
        "Unassigned"
      }
      
      # Manejar casos donde current_id es NA o tiene múltiples valores
      current_id <- if (length(current_id) == 0 || all(is.na(current_id))) {
        "Unassigned"
      } else {
        current_id[1]  # Tomar el primer valor si hay múltiples
      }
      
      fluidRow(
        column(6, p(strong(paste("Observation:", obs)))),
        column(6, selectInput(
          paste0("id_", i), NULL,
          choices = c("Unassigned", valid_ids),
          selected = current_id
        ))
      )
    })
  })
  
 
  
  output$phase_assignment_ui <- renderUI({
    # req(rv$initialized, rv$unique_obs, input$possible_phases,
    #     input$assignment_type %in% c("phase", "id_phase", "phase_group", "all"))
    req(rv$initialized, rv$unique_obs, input$possible_phases,
        "phase" %in% input$assignment_type)
    
    # Obtener todas las fases posibles (combinando predefinidas y existentes)
    predefined_phases <- trimws(unlist(strsplit(input$possible_phases, ",")))
    
    # Si hay datos cargados con fases, añadirlas a las opciones
    if (!is.null(rv$data) && "Treatment_Phase" %in% names(rv$data)) {
      existing_phases <- unique(na.omit(rv$data$Treatment_Phase))
      all_phases <- unique(c(predefined_phases, existing_phases))
    } else {
      all_phases <- predefined_phases
    }
    
    # Ordenar las fases alfabéticamente
    all_phases <- sort(all_phases)
    
    lapply(seq_along(rv$unique_obs), function(i) {
      obs <- rv$unique_obs[i]
      current_phase <- if (!is.null(rv$data$Treatment_Phase) && 
                           !is.na(rv$data$Treatment_Phase[rv$data[[input$observation_col]] == obs][1])) {
        rv$data$Treatment_Phase[rv$data[[input$observation_col]] == obs][1]
      } else {
        "Unassigned"
      }
      
      fluidRow(
        column(6, p(strong(paste("Observation:", obs)))),
        column(6, selectInput(
          paste0("phase_", i), NULL,
          choices = c("Unassigned", all_phases),
          selected = current_phase
        ))
      )
    })
  })
  
  
  output$group_assignment_ui <- renderUI({
    # req(rv$initialized, input$predefined_groups,
    #     input$assignment_type %in% c("group", "id_group", "phase_group", "all"))
    req(rv$initialized, input$predefined_groups,
        "group" %in% input$assignment_type)
    
    # Obtener los IDs según la fuente seleccionada
    if (input$id_source == "existing" && !is.null(input$existing_id_col) && input$existing_id_col != "") {
      req(input$existing_id_col %in% names(rv$data))
      unique_ids <- unique(na.omit(rv$data[[input$existing_id_col]]))
    } else {
      unique_ids <- unique(na.omit(rv$data$ID))
    }
    
    if (length(unique_ids) == 0) {
      return(div(class = "alert alert-warning", 
                 "There are no IDs available. Please assign IDs firt."))
    }
    
    predefined_groups <- trimws(unlist(strsplit(input$predefined_groups, ",")))
    
    lapply(seq_along(unique_ids), function(i) {
      id <- unique_ids[i]
      current_group <- if (input$id_source == "existing" && !is.null(input$existing_id_col)) {
        unique(rv$data$Group[rv$data[[input$existing_id_col]] == id])
      } else {
        unique(rv$data$Group[rv$data$ID == id])
      }
      current_group <- if (length(current_group) == 1) current_group else "Unassigned"
      
      fluidRow(
        column(6, p(strong(paste("ID:", id)))),
        column(6, selectInput(
          paste0("group_", i), NULL,
          choices = c("Unassigned", predefined_groups),
          selected = current_group
        ))
      )
    })
  })

  
  observe({
    req(rv$initialized, rv$data)
    
    # Actualizar IDs
    if ("id" %in% input$assignment_type) {
      lapply(seq_along(rv$unique_obs), function(i) {
        observeEvent(input[[paste0("id_", i)]], {
          obs <- rv$unique_obs[i]
          new_id <- if (input[[paste0("id_", i)]] == "Unassigned") NA else input[[paste0("id_", i)]]
          rv$data$ID[rv$data[[input$observation_col]] == obs] <- new_id
          
          # Actualizar también la columna original si usamos IDs existentes
          if ("group" %in% input$assignment_type && 
              input$id_source == "existing" && 
              !is.null(input$existing_id_col) && 
              input$existing_id_col != "") {
            rv$data[[input$existing_id_col]][rv$data[[input$observation_col]] == obs] <- new_id
          }
          
          rv$unique_ids <- unique(na.omit(rv$data$ID))
        })
      })
    }
    
    # Actualizar Phases
    if ("phase" %in% input$assignment_type) {
      lapply(seq_along(rv$unique_obs), function(i) {
        observeEvent(input[[paste0("phase_", i)]], {
          obs <- rv$unique_obs[i]
          new_phase <- if (input[[paste0("phase_", i)]] == "Unassigned") NA else input[[paste0("phase_", i)]]
          rv$data$Treatment_Phase[rv$data[[input$observation_col]] == obs] <- new_phase
        })
      })
    }
    
    # Actualizar Groups
    if ("group" %in% input$assignment_type) {
      if (input$id_source == "existing" && !is.null(input$existing_id_col) && input$existing_id_col != "") {
        current_ids <- unique(na.omit(rv$data[[input$existing_id_col]]))
        id_col <- input$existing_id_col
      } else {
        current_ids <- unique(na.omit(rv$data$ID))
        id_col <- "ID"
      }
      
      if (length(current_ids) > 0) {
        lapply(seq_along(current_ids), function(i) {
          observeEvent(input[[paste0("group_", i)]], {
            id <- current_ids[i]
            new_group <- if (input[[paste0("group_", i)]] == "Unassigned") NA else input[[paste0("group_", i)]]
            rv$data$Group[rv$data[[id_col]] == id] <- new_group
          })
        })
      }
    }
  })
  
  # Observer separado solo para actualizar unique_ids cuando cambian los datos relevantes
  observe({
    req(rv$data)
    
    # Actualizar unique_ids cuando:
    # 1. Cambian los IDs
    # 2. Cambia la columna de ID existente seleccionada
    # 3. Se inicializa la asignación
    
    if (input$id_source == "existing" && !is.null(input$existing_id_col) && input$existing_id_col != "") {
      rv$unique_ids <- unique(na.omit(rv$data[[input$existing_id_col]]))
    } else {
      rv$unique_ids <- unique(na.omit(rv$data$ID))
    }
  }) %>% bindEvent(
    rv$data,
    input$existing_id_col,
    input$id_source,
    input$init_assign
  )

  
  output$id_summary_table <- renderTable({
    # req(rv$initialized, rv$data, input$max_id,
    #     input$assignment_type %in% c("id", "id_phase", "id_group", "all"))
    req(rv$initialized, rv$data, input$max_id, "id" %in% input$assignment_type)
    
    valid_ids <- as.character(seq(1, input$max_id))
    
    data.frame(
      ID = c(valid_ids, "Unassigned"),
      Count = c(
        sapply(valid_ids, function(id) sum(rv$data$ID == id, na.rm = TRUE)),
        sum(is.na(rv$data$ID))
      )
    )
  })
  
  output$phase_summary_table <- renderTable({
    # req(rv$initialized, rv$data, input$possible_phases,
    #     input$assignment_type %in% c("phase", "id_phase", "phase_group", "all"))
    req(rv$initialized, rv$data, input$possible_phases, "phase" %in% input$assignment_type)
    
    # Obtener todas las fases posibles
    predefined_phases <- trimws(unlist(strsplit(input$possible_phases, ",")))
    if (!is.null(rv$data) && "Treatment_Phase" %in% names(rv$data)) {
      existing_phases <- unique(na.omit(rv$data$Treatment_Phase))
      all_phases <- unique(c(predefined_phases, existing_phases))
    } else {
      all_phases <- predefined_phases
    }
    
    data.frame(
      Phase = c(sort(all_phases), "Unassigned"),
      Count = c(
        sapply(sort(all_phases), function(p) sum(rv$data$Treatment_Phase == p, na.rm = TRUE)),
        sum(is.na(rv$data$Treatment_Phase))
      )
    )
  })
  
  output$group_summary_table <- renderTable({
    # req(rv$initialized, rv$data, input$predefined_groups,
    #     input$assignment_type %in% c("group", "id_group", "phase_group", "all"))
    req(rv$initialized, rv$data, input$predefined_groups, "group" %in% input$assignment_type)
    
    predefined_groups <- trimws(unlist(strsplit(input$predefined_groups, ",")))
    
    data.frame(
      Group = c(predefined_groups, "Unassigned"),
      Count = c(
        sapply(predefined_groups, function(g) sum(rv$data$Group == g, na.rm = TRUE)),
        sum(is.na(rv$data$Group))
      )
    )
  })
  
  # output$download <- downloadHandler(
  #   filename = function() {
  #     paste0("assigned_data_", Sys.Date(), ".",
  #            ifelse(input$download_format == "xlsx", "xlsx", "csv"))
  #   },
  #   content = function(file) {
  #     if (input$download_format == "xlsx") {
  #       write_xlsx(rv$data, file)
  #     } else {
  #       # write.csv(rv$data, file, row.names = FALSE, fileEncoding = "UTF-8")
  #       write_excel_csv(rv$data, file)
  #     }
  # 
  #     # Asegurar que el archivo se escriba completamente
  #     Sys.sleep(0.5)
  #     return(file)
  #   }
  # )
  # output$download <- downloadHandler(
  #   filename = function() {
  #     paste0("assigned_data_", Sys.Date(), ".", 
  #            ifelse(input$download_format == "xlsx", "xlsx", "csv"))
  #   },
  #   content = function(file) {
  #     req(input$observation_col)  # Asegurar que hay columna de observación seleccionada
  #     
  #     # Crear datos temporales para manejar casos vacíos
  #     download_data <- if (is.null(rv$data) || nrow(rv$data) == 0) {
  #       data.frame(
  #         Observation = character(),
  #         ID = character(),
  #         Treatment_Phase = character(),
  #         Group = character(),
  #         stringsAsFactors = FALSE
  #       )
  #     } else {
  #       # Columnas base (observación + las no asignables)
  #       base_cols <- unique(c(input$observation_col, 
  #                             names(rv$data)[!names(rv$data) %in% c("ID", "Treatment_Phase", "Group")]))
  #       
  #       # Determinar columnas adicionales según "What to Assign"
  #       additional_cols <- switch(input$assignment_type,
  #                                 "id" = "ID",
  #                                 "phase" = "Treatment_Phase",
  #                                 "group" = "Group",
  #                                 "id_phase" = c("ID", "Treatment_Phase"),
  #                                 "id_group" = c("ID", "Group"),
  #                                 "phase_group" = c("Treatment_Phase", "Group"),
  #                                 "all" = c("ID", "Treatment_Phase", "Group"))
  #       
  #       # Seleccionar columnas finales
  #       final_cols <- unique(c(base_cols, additional_cols))
  #       rv$data[, final_cols, drop = FALSE]
  #     }
  #     
  #     # Generar el archivo
  #     if (input$download_format == "xlsx") {
  #       write_xlsx(download_data, file)
  #     } else {
  #       readr::write_excel_csv(download_data, file)
  #     }
  #   }
  # )
  output$download <- downloadHandler(
    filename = function() {
      paste0("assigned_data_", Sys.Date(), ".", 
             ifelse(input$download_format == "xlsx", "xlsx", "csv"))
    },
    content = function(file) {
      req(input$observation_col, rv$data)
      
      # Columnas base (siempre incluidas)
      base_cols <- input$observation_col
      
      # Columnas adicionales según selección
      additional_cols <- character()
      if ("id" %in% input$assignment_type) additional_cols <- c(additional_cols, "ID")
      if ("phase" %in% input$assignment_type) additional_cols <- c(additional_cols, "Treatment_Phase")
      if ("group" %in% input$assignment_type) additional_cols <- c(additional_cols, "Group")
      
      # Columnas no asignables (que no son ID, Phase o Group)
      other_cols <- setdiff(names(rv$data), c("ID", "Treatment_Phase", "Group"))
      
      # Crear subset de datos
      selected_cols <- unique(c(base_cols, other_cols, additional_cols))
      download_data <- rv$data[, selected_cols, drop = FALSE]
      
      # Generar archivo
      if (input$download_format == "xlsx") {
        write_xlsx(download_data, file)
      } else {
        readr::write_excel_csv(download_data, file)
      }
    }
  )
}

